<template>
  <main class="sensaciones" :style="{'--accent':settings.primary,'--secondary':settings.secondary,'--bg':settings.background,'--ink':ink}">
    <div class="premium-shell">
    <q-banner v-if="offlinePreview" class="bg-deep-orange-10 text-white">Vista previa de diseño · Sin conexión a producción. No contiene trabajos ni clientes reales.</q-banner>
    <section v-if="mode==='home'" class="hero premium-hero"><div class="hero-copy"><span>ARTE · CREATIVIDAD · PRODUCCIÓN</span><h1>{{headline}}</h1><p>{{tagline}}</p><div class="hero-actions"><q-btn color="deep-orange" unelevated icon="play_circle" label="Explorar videos" no-caps @click="exploreVideos"/><q-btn outline color="orange-3" icon="photo_library" label="Galería fotográfica" no-caps to="/sensaciones/fotografias"/></div></div><div class="hero-art" aria-hidden="true"><q-icon name="movie_creation"/></div></section>
    <div v-if="mode==='home'" class="feature-links"><router-link to="/sensaciones/portafolio"><q-icon name="collections_bookmark" size="32px"/><strong>Proyectos y álbumes</strong><span>Descubre historias completas</span></router-link><router-link to="/sensaciones/antes-despues"><q-icon name="compare" size="32px"/><strong>Antes y después</strong><span>El arte de la transformación</span></router-link><router-link to="/sensaciones/servicios"><q-icon name="camera_alt" size="32px"/><strong>Servicios profesionales</strong><span>Conversemos sobre tu idea</span></router-link></div>
    <section v-if="mode==='home' && settings.intro_url" class="catalog intro"><h2>Video de presentación</h2><SensacionesPlayer :src="mediaUrl(settings.intro_url)" :poster="mediaUrl(settings.intro_poster_url)" :logo="mediaUrl(settings.logo_url)" :title="settings.brand"/></section>
    <section v-if="mode==='home'||mode==='photo'" ref="gallery" class="catalog"><div class="catalog-head"><div><span class="kicker">TRABAJOS SELECCIONADOS</span><h2>{{mode==='photo'?'Fotografías y diseños':'Nuestras producciones'}}</h2></div><router-link to="/sensaciones/portafolio">Ver álbumes y proyectos →</router-link></div><q-form class="catalog-filters" @submit="filter"><q-btn-toggle v-if="mode==='home'" v-model="kind" :options="[{label:'Todo',value:''},{label:'Fotografías',value:'photo'},{label:'Videos',value:'video'}]" no-caps unelevated toggle-color="deep-orange" color="grey-9" text-color="white" @update:model-value="filter"/><q-input outlined dense :dark="ink!=='#111111'" v-model="search" label="Buscar trabajos" clearable maxlength="100"><template #append><q-btn flat round icon="search" type="submit" aria-label="Buscar"/></template></q-input></q-form>
      <q-banner v-if="error" class="bg-grey-10 text-white">{{error}} <q-btn flat label="Actualizar" @click="load"/></q-banner>
      <q-spinner v-else-if="loading" color="deep-orange" size="40px"/>
      <p v-else-if="!items.length">{{offlinePreview ? 'El catálogo se habilitará al conectar el entorno de pruebas.' : 'Todavía no hay trabajos publicados.'}}</p>
      <div class="media-grid portfolio-grid"><article v-for="item in items" :key="item.id"><SensacionesPlayer v-if="item.kind==='video'" :src="mediaUrl(item.url)" :poster="mediaUrl(item.poster_url)" :title="item.title" :logo="mediaUrl(settings.logo_url)"/><button v-else class="photo-open" @click="activePhoto=item" :aria-label="'Ampliar '+item.title"><img :src="mediaUrl(item.url)" :alt="item.title" loading="lazy"/><span><q-icon name="fullscreen"/> Ampliar</span></button><h3>{{item.title}}</h3><p>{{item.description}}</p></article></div>
      <q-pagination v-if="last>1" v-model="page" :max="last" color="deep-orange" @update:model-value="load"/>
    </section><section v-if="mode==='home'||mode==='services'" class="catalog" id="servicios"><h2>Servicios profesionales</h2><div class="media-grid"><article v-for="(service,i) in settings.services" :key="i"><h3>{{service.title}}</h3><p>{{service.description}}</p><a v-if="settings.whatsapp" class="contact" :href="whatsapp(service.title)" target="_blank" rel="noopener noreferrer">Consultar por WhatsApp</a></article></div><p v-if="settings.whatsapp"><a class="contact" :href="whatsapp('servicios audiovisuales')" target="_blank" rel="noopener noreferrer">Contactar al estudio</a></p></section><section v-if="mode==='home'||mode==='community'" class="community-card"><div><span class="kicker">ESPACIO INDEPENDIENTE</span><h2>Comunidad creativa</h2><p>Un espacio gratuito para compartir talento audiovisual, separado del portafolio oficial. Las publicaciones requerirán revisión y autorización del estudio.</p><p v-if="mode==='community'">Próximamente: las inscripciones y publicaciones de la comunidad todavía no están habilitadas.</p></div><q-btn v-if="mode==='home'" unelevated color="deep-orange" label="Conocer la comunidad" icon-right="arrow_forward" no-caps to="/sensaciones/comunidad"/></section></div><footer>{{settings.brand}} · Arte, creatividad y producción.</footer><q-dialog :model-value="!!activePhoto" @update:model-value="v=>{if(!v)activePhoto=null}" maximized><div class="photo-view"><q-btn flat color="white" icon="close" label="Cerrar" @click="activePhoto=null"/><img v-if="activePhoto" :src="mediaUrl(activePhoto.url)" :alt="activePhoto.title"/><p>{{activePhoto?.title}}</p></div></q-dialog>
  </main>
</template>
<script setup>
import { ref, computed, onMounted, onBeforeUnmount } from 'vue'
import {useRoute} from 'vue-router'
const route=useRoute()
const mode=route.meta.portfolioMode||'home'
import SensacionesPlayer from '../components/SensacionesPlayer.vue'
import { mediaUrl } from '../services/sensacionesMedia'
import { api } from '../boot/axios'
const offlinePreview=import.meta.env.VITE_SENSACIONES_OFFLINE_PREVIEW === '1'
const items=ref([]), page=ref(1), last=ref(1), error=ref(''), loading=ref(false), gallery=ref(null),kind=ref(mode==='photo'?'photo':''),search=ref(''),activePhoto=ref(null)
function exploreVideos(){kind.value='video';filter();gallery.value?.scrollIntoView({behavior:'smooth'})}
function filter(){page.value=1;load()}
async function load(){
  if(offlinePreview) return
  loading.value=true; error.value=''
  try {const {data}=await api.get('/sensaciones/media',{params:{page:page.value,kind:kind.value||undefined,q:search.value||undefined}});items.value=data.data;last.value=data.last_page}
  catch {error.value='El portafolio está en preparación. Vuelve pronto para conocer nuestras producciones.'}
  finally {loading.value=false}
}
const settings=ref({brand:'Sensaciones Audiovisuales Digital',headline:'No solo capturamos momentos. Creamos sensaciones.',tagline:'Videos, fotografías y diseños con una mirada propia.',primary:'#FF681E',secondary:'#980B20',background:'#101014',services:[{title:'Producción audiovisual',description:'Videos, eventos y producciones creativas.'},{title:'Fotografía profesional',description:'Sesiones fotográficas y edición.'},{title:'Publicidad y diseño',description:'Contenido creativo para marcas y empresas.'}]})
// Mantener la frase original como valor visual predeterminado; respetar otros textos guardados.
const headline=computed(()=>settings.value.headline==='Historias que merecen ser vistas.'?'No solo capturamos momentos. Creamos sensaciones.':settings.value.headline)
const tagline=computed(()=>settings.value.tagline==='Fotografía, video y creatividad con una mirada propia.'?'Videos, fotografías y diseños con una mirada propia.':settings.value.tagline)
const ink=computed(()=>{const h=settings.value.background.slice(1);const rgb=[0,2,4].map(i=>parseInt(h.slice(i,i+2),16)/255).map(v=>v<=.04045?v/12.92:((v+.055)/1.055)**2.4);return .2126*rgb[0]+.7152*rgb[1]+.0722*rgb[2]>.179?'#111111':'#f5f4f2'})
const whatsapp=service=>'https://wa.me/'+settings.value.whatsapp+'?text='+encodeURIComponent('Hola, me interesa '+service+'.')
let alive=true
const previousTitle=document.title
let descriptionNode=null,previousDescription=null,createdDescription=false
async function loadSettings(){try{const {data}=await api.get('/sensaciones/settings');if(!alive)return;settings.value=data;document.title=data.seo_title;descriptionNode=document.querySelector('meta[name="description"]');if(!descriptionNode){descriptionNode=document.createElement('meta');descriptionNode.name='description';document.head.append(descriptionNode);createdDescription=true}else previousDescription=descriptionNode.getAttribute('content');descriptionNode.content=data.seo_description}catch{/* el catálogo conserva su propio estado de error */}}
onMounted(()=>{if(offlinePreview){document.title='Sensaciones Digital | Vista previa'}else{if(mode==='home'||mode==='photo')load();loadSettings()}})
onBeforeUnmount(()=>{alive=false;document.title=previousTitle;if(createdDescription)descriptionNode?.remove();else if(descriptionNode){if(previousDescription===null)descriptionNode.removeAttribute('content');else descriptionNode.content=previousDescription}})
</script>
<style scoped>
