.brand img{max-width:220px;max-height:65px;object-fit:contain}.contact{display:inline-block;background:#24242a;color:#fff!important;padding:10px 14px;border:1px solid var(--accent);border-radius:8px;margin:10px 14px}.intro{max-width:1100px;margin:auto}.hero .q-btn{background:var(--accent)!important;color:#111!important}
.brand-default{display:flex;align-items:center;gap:10px;letter-spacing:.06em}.brand-default img{width:44px;height:44px}.sensaciones nav div{display:flex;flex-wrap:wrap;gap:12px;align-items:center}
.hero-actions{display:flex;gap:12px;flex-wrap:wrap}.catalog-head{display:flex;align-items:end;justify-content:space-between;gap:16px;flex-wrap:wrap}.catalog-head h2{margin:8px 0 20px}.kicker{font-size:11px;font-weight:800;letter-spacing:.17em;color:var(--ink)}.catalog-filters{display:flex;gap:16px;justify-content:space-between;flex-wrap:wrap;margin-bottom:24px}.catalog-filters .q-input{min-width:min(100%,260px)}.photo-open{position:relative;width:100%;padding:0;border:0;background:#101014;cursor:zoom-in;display:block}.photo-open span{position:absolute;bottom:10px;right:10px;background:#101014db;color:white;border-radius:6px;padding:6px 9px;font-size:12px}.photo-view{background:#08080a;color:#fff;display:flex;align-items:center;justify-content:center;flex-direction:column;padding:12px}.photo-view img{max-width:100%;max-height:82vh;object-fit:contain}

.premium-shell{max-width:1660px;margin:auto;padding:32px clamp(18px,3.7vw,60px) 60px}.premium-hero{position:relative;isolation:isolate;overflow:hidden;display:grid;grid-template-columns:minmax(0,1.55fr) minmax(0,.75fr);align-items:center;min-height:clamp(360px,43.5vw,720px);padding:clamp(28px,4.6vw,76px);border:1px solid #553124;border-radius:28px;background:radial-gradient(ellipse at 90% 30%,color-mix(in srgb,var(--accent) 38%,transparent),transparent 57%),linear-gradient(130deg,#181820,#101014)}.premium-hero::after{content:"";position:absolute;inset:0;z-index:-1;pointer-events:none;background:repeating-linear-gradient(120deg,transparent 0 60px,#ffffff05 61px 62px)}.premium-hero h1{font-family:Inter,system-ui,sans-serif;font-size:clamp(2.7rem,5.8vw,5.9rem);line-height:1.06;letter-spacing:-.065em;font-weight:900;max-width:930px;margin:24px 0}.premium-hero span{color:var(--accent);font-weight:850;letter-spacing:.16em;font-size:.85rem}.premium-hero p{font-size:clamp(15px,1.2vw,19px);line-height:1.65}.hero-art{display:grid;place-items:center;color:#ff9b66}.hero-art .q-icon{font-size:clamp(120px,19vw,300px);transform:rotate(-12deg);filter:drop-shadow(0 20px 45px #0008)}.hero-actions{margin-top:32px}.hero-actions .q-btn{border-radius:10px;font-weight:750;padding:8px 18px}.hero-actions .q-btn:first-child{background:var(--accent)!important;color:white!important}.hero-actions .q-btn:last-child{background:transparent!important;color:#ffc478!important}.feature-links{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:18px;margin:22px 0 34px}.feature-links a{display:grid;gap:10px;border:1px solid #33343e;border-radius:16px;padding:26px;background:#191a20;color:#fff}.feature-links a:hover{border-color:var(--accent)}.feature-links .q-icon{color:var(--accent)}.feature-links strong{font-size:18px}.feature-links span{font-size:14px;color:#aaa}.premium-shell .catalog{padding:28px 0;scroll-margin-top:100px}.community-card{display:flex;align-items:center;justify-content:space-between;gap:20px;flex-wrap:wrap;margin:32px 0;padding:28px;border:1px solid #553124;border-radius:18px;background:linear-gradient(125deg,#36221c,#191a20);color:#fff}.community-card p{color:#c7c4c3;max-width:750px}.community-card h2{font-size:28px;margin:12px 0}.community-card .kicker{color:#ff985c}@media(max-width:760px){.premium-hero{grid-template-columns:1fr;min-height:0}.premium-hero h1{font-size:clamp(2.45rem,8vw,3.5rem)}.hero-art{display:none}.feature-links{grid-template-columns:1fr}.feature-links a{padding:19px}.premium-shell{padding-top:20px}}
.portfolio-grid{grid-template-columns:repeat(auto-fill,minmax(min(100%,300px),1fr))}
</style>
